<?php
function shop_migrate_options(PDO $db,string $id,bool $sqlite): void {
    $suffix=$sqlite?'':' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
    foreach([
        "shop_documents (id $id,slug VARCHAR(80) NOT NULL UNIQUE,title VARCHAR(180) NOT NULL,category VARCHAR(30) NOT NULL,draft_content TEXT NOT NULL,draft_file VARCHAR(180),published_version INT,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP)",
        "shop_document_versions (id $id,document_id INT NOT NULL,version_no INT NOT NULL,title VARCHAR(180) NOT NULL,content TEXT NOT NULL,source_file VARCHAR(180),pdf_file VARCHAR(180),pdf_hash VARCHAR(64),created_by INT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(document_id,version_no),FOREIGN KEY(document_id) REFERENCES shop_documents(id))",
        "shop_product_modules (id $id,product_id INT NOT NULL,label VARCHAR(120) NOT NULL,description TEXT NOT NULL,unit_label VARCHAR(60) NOT NULL,target VARCHAR(40) NOT NULL,unit_value INT NOT NULL DEFAULT 1,net_cents INT NOT NULL DEFAULT 0,min_qty INT NOT NULL DEFAULT 0,max_qty INT NOT NULL DEFAULT 10,default_qty INT NOT NULL DEFAULT 0,control VARCHAR(20) NOT NULL DEFAULT 'number',active INT NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,FOREIGN KEY(product_id) REFERENCES shop_products(id))",
        "shop_product_recommendations (product_id INT PRIMARY KEY,targets TEXT NOT NULL,FOREIGN KEY(product_id) REFERENCES shop_products(id))",
        "shop_payment_attestations (id $id,order_id INT NOT NULL,invoice_id INT,payment_id INT UNIQUE,admin_id INT NOT NULL,source VARCHAR(20) NOT NULL,reference VARCHAR(120) NOT NULL,reason TEXT NOT NULL,token VARCHAR(64) NOT NULL UNIQUE,allow_provisioning INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES shop_orders(id))",
        "shop_child_credentials (child_id INT PRIMARY KEY,secret TEXT NOT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(child_id) REFERENCES shop_hosting_children(id) ON DELETE CASCADE)",
        "shop_provider_account_logins (customer_id INT NOT NULL,provider VARCHAR(30) NOT NULL,secret TEXT NOT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(customer_id,provider),FOREIGN KEY(customer_id,provider) REFERENCES shop_provider_accounts(customer_id,provider))",
        "shop_module_catalog (id $id,category VARCHAR(40) NOT NULL,label VARCHAR(120) NOT NULL,description TEXT NOT NULL,unit_label VARCHAR(60) NOT NULL,target VARCHAR(40) NOT NULL,unit_value INT NOT NULL DEFAULT 1,net_cents INT NOT NULL DEFAULT 0,min_qty INT NOT NULL DEFAULT 0,max_qty INT NOT NULL DEFAULT 10,default_qty INT NOT NULL DEFAULT 0,control VARCHAR(20) NOT NULL DEFAULT 'number',options_json TEXT NOT NULL,active INT NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0)",
        "shop_product_module_bindings (module_id INT PRIMARY KEY,catalog_id INT NOT NULL,mode VARCHAR(20) NOT NULL DEFAULT 'optional',included_qty INT NOT NULL DEFAULT 1,FOREIGN KEY(module_id) REFERENCES shop_product_modules(id),FOREIGN KEY(catalog_id) REFERENCES shop_module_catalog(id))",
        "shop_product_configurators (product_id INT PRIMARY KEY,enabled INT NOT NULL DEFAULT 0,FOREIGN KEY(product_id) REFERENCES shop_products(id))",
        "shop_module_intents (id $id,parent_order_id INT NOT NULL,customer_id INT NOT NULL,module_id INT NOT NULL,snapshot TEXT NOT NULL,checkout_key VARCHAR(64) NOT NULL UNIQUE,order_id INT UNIQUE,state VARCHAR(30) NOT NULL DEFAULT 'selected',initial_net_cents INT NOT NULL DEFAULT 0,initial_gross_cents INT NOT NULL DEFAULT 0,recurring_net_cents INT NOT NULL DEFAULT 0,recurring_gross_cents INT NOT NULL DEFAULT 0,initial_until INT NOT NULL DEFAULT 0,first_settled INT NOT NULL DEFAULT 0,applied_at INT NOT NULL DEFAULT 0,payload TEXT NOT NULL,last_error VARCHAR(500),created_ts INT NOT NULL,FOREIGN KEY(parent_order_id) REFERENCES shop_orders(id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(order_id) REFERENCES shop_orders(id))",
        "shop_service_module_profiles (service_id INT PRIMARY KEY,parent_order_id INT NOT NULL,base_profile TEXT NOT NULL,revision INT NOT NULL DEFAULT 0,FOREIGN KEY(service_id) REFERENCES shop_services(id),FOREIGN KEY(parent_order_id) REFERENCES shop_orders(id))",
        "shop_network_addresses (id $id,address VARCHAR(45) NOT NULL UNIQUE,prefix_len INT NOT NULL DEFAULT 32,mac VARCHAR(17),gateway VARCHAR(45) NOT NULL,bridge VARCHAR(40) NOT NULL,node VARCHAR(80) NOT NULL DEFAULT '',provider_ref VARCHAR(253) NOT NULL DEFAULT '',state VARCHAR(30) NOT NULL DEFAULT 'review',order_id INT UNIQUE,service_id INT UNIQUE,notes TEXT NOT NULL,FOREIGN KEY(order_id) REFERENCES shop_orders(id),FOREIGN KEY(service_id) REFERENCES shop_services(id))",
        "shop_server_templates (id $id,name VARCHAR(120) NOT NULL,description TEXT NOT NULL,node VARCHAR(80) NOT NULL,archive VARCHAR(253) NOT NULL,storage VARCHAR(80) NOT NULL,source_url VARCHAR(500) NOT NULL,settings TEXT NOT NULL,active INT NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0)",
        "shop_server_template_bindings (product_id INT NOT NULL,template_id INT NOT NULL,PRIMARY KEY(product_id,template_id),FOREIGN KEY(product_id) REFERENCES shop_products(id),FOREIGN KEY(template_id) REFERENCES shop_server_templates(id))",
        "shop_server_operations (id $id,service_id INT NOT NULL,kind VARCHAR(30) NOT NULL,state VARCHAR(30) NOT NULL DEFAULT 'queued',phase VARCHAR(40) NOT NULL DEFAULT 'start',payload TEXT NOT NULL,last_error VARCHAR(500),operation_key VARCHAR(64) NOT NULL UNIQUE,created_ts INT NOT NULL,locked_until INT NOT NULL DEFAULT 0,lock_token VARCHAR(64),FOREIGN KEY(service_id) REFERENCES shop_services(id))",
        "shop_dns_jobs (order_id INT PRIMARY KEY,domain VARCHAR(253) NOT NULL,state VARCHAR(30) NOT NULL DEFAULT 'pending',records TEXT NOT NULL,payload TEXT NOT NULL,last_error VARCHAR(500),locked_until INT NOT NULL DEFAULT 0,lock_token VARCHAR(64),FOREIGN KEY(order_id) REFERENCES shop_orders(id))",
        "shop_infrastructure_sync (provider VARCHAR(30) PRIMARY KEY,state VARCHAR(30) NOT NULL DEFAULT 'pending',next_run INT NOT NULL DEFAULT 0,last_success INT NOT NULL DEFAULT 0,last_error VARCHAR(500),summary TEXT,locked_until INT NOT NULL DEFAULT 0,lock_token VARCHAR(64))",
        "shop_template_runners (node VARCHAR(80) PRIMARY KEY,secret_token TEXT NOT NULL,connection_id VARCHAR(64) NOT NULL,seen_ts INT NOT NULL DEFAULT 0,last_status VARCHAR(120) NOT NULL DEFAULT '')",
        "shop_template_builds (id $id,template_id INT NOT NULL,node VARCHAR(80) NOT NULL,connection_id VARCHAR(64) NOT NULL,payload TEXT NOT NULL,state VARCHAR(30) NOT NULL DEFAULT 'queued',vmid INT NOT NULL DEFAULT 0,archive VARCHAR(253) NOT NULL DEFAULT '',last_error VARCHAR(500),created_ts INT NOT NULL,started_ts INT NOT NULL DEFAULT 0,updated_ts INT NOT NULL DEFAULT 0,FOREIGN KEY(template_id) REFERENCES shop_server_templates(id))",
        "shop_hosting_domain_verifications (order_id INT PRIMARY KEY,customer_id INT NOT NULL,domain VARCHAR(253) NOT NULL,token VARCHAR(64) NOT NULL,state VARCHAR(30) NOT NULL DEFAULT 'pending',confirmed_ts INT NOT NULL DEFAULT 0,verified_ts INT NOT NULL DEFAULT 0,activated_ts INT NOT NULL DEFAULT 0,expires_ts INT NOT NULL,next_check INT NOT NULL DEFAULT 0,last_error VARCHAR(500),locked_until INT NOT NULL DEFAULT 0,lock_token VARCHAR(64),FOREIGN KEY(order_id) REFERENCES shop_orders(id),FOREIGN KEY(customer_id) REFERENCES customers(id))",
        "shop_hosting_mail_dns (domain VARCHAR(253) PRIMARY KEY,customer_id INT NOT NULL,mail_domain_id INT NOT NULL,ispconfig_connection_id VARCHAR(64) NOT NULL,ovh_connection_id VARCHAR(64) NOT NULL DEFAULT '',record TEXT NOT NULL,dns_mode VARCHAR(30) NOT NULL,state VARCHAR(30) NOT NULL,last_error VARCHAR(500),updated_ts INT NOT NULL,locked_until INT NOT NULL DEFAULT 0,lock_token VARCHAR(64),FOREIGN KEY(customer_id) REFERENCES customers(id))",
    ] as $table)$db->exec('CREATE TABLE IF NOT EXISTS '.$table.$suffix);
}
